#!/usr/bin/env Rscript
source("code/01_common.R");out<-file.path(r2,"TNK");dir.create(out,recursive=TRUE,showWarnings=FALSE);t0<-Sys.time();q1<-file.path(r1,"TNK","TNK_round1_clustered.qs");o<-qs::qread(q1);stopifnot(ncol(o)==124746,"cluster_v2_round1"%in%colnames(o[[]]),all(c("counts","data")%in%Layers(o[["RNA"]],search=NA)));DefaultAssay(o)<-"RNA";if("scale.data"%in%Layers(o[["RNA"]],search=NA))LayerData(o,assay="RNA",layer="scale.data")<-NULL;o<-FindVariableFeatures(o,assay="RNA",selection.method="vst",nfeatures=3000,verbose=TRUE);o<-ScaleData(o,assay="RNA",features=VariableFeatures(o),verbose=TRUE);o<-RunPCA(o,assay="RNA",features=VariableFeatures(o),npcs=50,reduction.name="pca_round2_common",seed.use=20260915,verbose=TRUE);o@misc$tnk_round2_common_parameters<-list(cells=ncol(o),HVG=3000,PCA=50,dims="1:30",seed=20260915,no_exclusions=TRUE);q<-file.path(out,"TNK_round2_common_preprocessed.qs");qs::qsave(o,q,preset="high",nthreads=16);write.csv(data.frame(cells=ncol(o),variable_features=length(VariableFeatures(o)),pca_dimensions=ncol(Embeddings(o[["pca_round2_common"]])),counts_present="counts"%in%Layers(o[["RNA"]],search=NA),data_present="data"%in%Layers(o[["RNA"]],search=NA),runtime_minutes=as.numeric(difftime(Sys.time(),t0,units="mins"))),file.path(out,"TNK_common_preprocessing_audit.csv"),row.names=FALSE);message("TNK_COMMON_READY")
